Signature: buffer_t* buffer_new_with_string_length(char *str, size_t len)
Description: /**
 * @brief Create a new buffer object referencing an existing string.
 *
 * Allocates a buffer_t structure that points to the provided string and sets
 * its length to the specified value. The buffer does not copy the string data;
 * it simply references the given memory.
 *
 * @param str Pointer to the string data to reference. May be NULL if len is 0.
 *            Caller retains ownership and must ensure the memory remains valid
 *            for the lifetime of the buffer.
 * @param len Number of bytes to reference from str.
 *
 * @return Pointer to a newly allocated buffer_t on success, or NULL if memory
 *         allocation fails.
 *
 * @note Memory: Caller must free the returned buffer_t, but not the string data.
 */
Dependencies: None

FUNCTION IMPLEMENTATION:
```c
// C program for the function called buffer_new_with_string_length
// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Target function implementation
buffer_t *
buffer_new_with_string_length(char *str, size_t len) {
  buffer_t *self = malloc(sizeof(buffer_t));
  if (!self) return NULL;
  self->len = len;
  self->data = self->alloc = str;
  return self;
}

